// Free-text fields (Plats/Operatör/Batch ID/Provsvars ID) shown at the top
// of the page, built the same way as the "analysdata" table below: a
// compound element that dispatches its own "input" event so it works as
// a `viewof`, with `.value` exposing all fields as one object.
viewof meta = {
  const platsInput = Object.assign(html`&lt;input type="text" class="meta-input" placeholder="Ange plats"&gt;`, {});
  const operatorInput = Object.assign(html`&lt;input type="text" class="meta-input" placeholder="Ange operatör"&gt;`, {});
  const batchInput = Object.assign(html`&lt;input type="text" class="meta-input" placeholder="Ange batch ID" maxlength="15"&gt;`, {});
  const provsvarsInput = Object.assign(html`&lt;input type="text" class="meta-input" placeholder="Ange provsvars ID"&gt;`, {});

  const container = html`&lt;div class="meta-row"&gt;
    &lt;label class="meta-field"&gt;Anläggning
      ${platsInput}
    &lt;/label&gt;
    &lt;label class="meta-field"&gt;Provsvrshanterare
      ${operatorInput}
    &lt;/label&gt;
    &lt;label class="meta-field"&gt;Batch ID
      ${batchInput}
    &lt;/label&gt;
    &lt;label class="meta-field"&gt;Provsvars ID
      ${provsvarsInput}
    &lt;/label&gt;
  &lt;/div&gt;`;

  function currentValue() {
    return {
      plats: platsInput.value,
      operator: operatorInput.value,
      batchId: batchInput.value,
      provsvarsId: provsvarsInput.value
    };
  }

  container.value = currentValue();

  for (const input of [platsInput, operatorInput, batchInput, provsvarsInput]) {
    input.addEventListener("input", () =&gt; {
      container.value = currentValue();
      container.dispatchEvent(new Event("input", {bubbles: true}));
    });
  }

  return container;
}







