function volymEnheter() {
  return [
    {unit: "g/L", toCanonical: d =&gt; d, fromCanonical: c =&gt; c},
    {unit: "mg/L", toCanonical: d =&gt; d / 1000, fromCanonical: c =&gt; c * 1000},
    {unit: "g/kg TS", toCanonical: (d, ts) =&gt; d * ts, fromCanonical: (c, ts) =&gt; c / ts},
    {unit: "%", toCanonical: d =&gt; d * 10, fromCanonical: c =&gt; c / 10}
  ];
}

// Units for a row whose canonical unit is mg/kg TS (a concentration
// relative to dry solids mass): matches the "μg/l; mg/L, mg/kg TS"
// dropdown list used by the Metaller rows.
function metallEnheter() {
  return [
    {unit: "mg/kg TS", toCanonical: d =&gt; d, fromCanonical: c =&gt; c},
    {unit: "mg/L", toCanonical: (d, ts) =&gt; d / ts, fromCanonical: (c, ts) =&gt; c * ts},
    {unit: "μg/L", toCanonical: (d, ts) =&gt; d / 1000 / ts, fromCanonical: (c, ts) =&gt; c * ts * 1000}
  ];
}

// Units for a row whose canonical unit is log10 cfu/ml (E. coli,
// Enterokocker): the dropdown offers linear colony counts in several
// bases, which relate to the canonical log value through log10/10^x —
// not a plain multiplicative factor — plus one (cfu/kg TS) that also
// needs the live TS fraction. A fixed `stepOverride` is used for these
// instead of scaling `p.step`, since a step size in log-space doesn't
// translate to a sensible linear step by simple multiplication.
function smittEnheter() {
  const toLog = v =&gt; (v &gt; 0 ? Math.log10(v) : -Infinity);
  return [
    {unit: "log10 cfu/ml", toCanonical: d =&gt; d, fromCanonical: c =&gt; c},
    {unit: "cfu/ml", toCanonical: d =&gt; toLog(d), fromCanonical: c =&gt; Math.pow(10, c), stepOverride: 100},
    {unit: "cfu/g", toCanonical: d =&gt; toLog(d), fromCanonical: c =&gt; Math.pow(10, c), stepOverride: 100},
    {unit: "cfu/100 ml", toCanonical: d =&gt; toLog(d / 100), fromCanonical: c =&gt; Math.pow(10, c) * 100, stepOverride: 1000},
    {unit: "cfu/kg TS", toCanonical: (d, ts) =&gt; toLog(d * ts), fromCanonical: (c, ts) =&gt; Math.pow(10, c) / ts, stepOverride: 1000}
  ];
}

